import manifest from "./scenes.manifest.json";

/** A point inside an image, in 0–1 units measured from its top-left corner. */
export type Point = readonly [x: number, y: number];

export interface SceneImage {
  src: string;
  width: number;
  height: number;
}

export interface SceneDef {
  id: string;
  /** Two-digit label shown in the interface: "01" … "06". */
  number: string;
  title: string;
  /** Narrative line. Text wrapped in *asterisks* is set in italics. */
  line: string;
  full: SceneImage;
  lite: SceneImage;
  /** Estimated depth map (1 = near, 0 = far), generated by `npm run depth`. */
  depth: SceneImage;
  /**
   * What the camera frames and pushes towards. On narrow screens, where only a
   * vertical slice of the picture fits, this is also what the crop is centred on.
   */
  focus: Point;
  /** Where gravity is felt in this picture — the black hole, once it is visible. */
  gravity: Point;
  /** How far gravity's influence extends, as a fraction of the picture's height. */
  reach: number;
  /** Radius of the black hole's dark disc, as a fraction of the picture's height (0 = not visible). */
  horizon: number;
  /** How strongly this picture's depth is exaggerated (1 = default). */
  relief: number;
}

