if (manifest.length !== copy.length) {
  throw new Error(`Expected ${copy.length} scene images in the manifest, found ${manifest.length}.`);
}

export const scenes: SceneDef[] = copy.map((scene, index) => {
  const entry = manifest[index];
  return {
    ...scene,
    id: entry.id,
    number: String(index + 1).padStart(2, "0"),
    full: entry.full,
    lite: entry.lite,
    depth: entry.depth,
  };
});

export const SCENE_COUNT = scenes.length;

/** Width ÷ height of the source pictures (they all share the same size). */
export const IMAGE_ASPECT = manifest[0].width / manifest[0].height;

export const project = {
  name: "Beyond",
  subtitle: "A journey through the unknown",
  closing: "We are infinite.",
} as const;

/**
 * How each new scene takes over from the previous one. Every pixel gets an
 * "arrival time" built from three ingredients, so no two transitions look alike:
 *
 *  - radial: distance from the transition's origin (an opening iris)
 *  - noise:  a cloud pattern (the scene seeps in organically)
 *  - luma:   brightness of the incoming picture (its light arrives first)
 *
 * `feather` softens the edge, `refract` bends the picture along that edge like a
 * lens, and `glow` tints it with light.
 */
export interface TransitionDef {
  radial: number;
  noise: number;
  luma: number;
  feather: number;
  refract: number;
  glow: readonly [r: number, g: number, b: number];
}

export const transitions: TransitionDef[] = [
  // The Void → Entering the Nebula: a portal opens in the distant glow, its edge a little ragged.
  { radial: 0.82, noise: 0.18, luma: 0, feather: 0.1, refract: 0.6, glow: [0.35, 0.5, 1.0] },
  // Entering → Through the Nebula: the clouds part along a torn, organic edge.
  { radial: 0.7, noise: 0.3, luma: 0, feather: 0.12, refract: 0.5, glow: [0.6, 0.4, 1.0] },
  // Through the Nebula → Distortion Ahead: a perfect gravitational lens sweeps the frame.
  { radial: 1, noise: 0.05, luma: 0, feather: 0.05, refract: 1, glow: [1.0, 0.6, 0.3] },
  // Distortion Ahead → Black Hole Reveal: the horizon itself is the portal.
  { radial: 1, noise: 0.04, luma: 0, feather: 0.045, refract: 0.9, glow: [1.0, 0.65, 0.25] },
  // Black Hole Reveal → Event Horizon: the plunge, edge trembling.
  { radial: 0.92, noise: 0.08, luma: 0, feather: 0.08, refract: 0.6, glow: [1.0, 0.72, 0.35] },
];
